import json,sys,re
data=json.load(sys.stdin)
elements=data['document']['elements']
for i, e in enumerate(elements):
    if e.get('type') == 'table' and e.get('content'):
        content = str(e.get('content',''))
        # Look for tables with Defense and on/off budget
        if 'Defense' in content and 'On-budget' in content and 'Off-budget' in content:
            # Check if there's a table that lists individual agencies with separate on/off columns
            # Look for pattern like Defense on-budget value and Defense off-budget value in same row
            if 'Defense' in content:
                # Check if this table has individual agency on/off breakdown
                lines = content.split('<tr>')
                for line in lines:
                    if 'Defense' in line and '<td>' in line:
                        cols = re.findall(r'<td>([^<]+)</td>', line)
                        if len(cols) > 2:
                            print('Columns:', cols[:15])
                            print('---')
" 2>/dev/null

